import { state } from '/static/v2/api.js';
import { hydrateIcons } from '/static/v2/icons.js';
import * as chat from '/static/v2/conversation.js';

state.session = { session_id: 'steering-fixture', workdir: '/fixture' };
state.view = 'chat';
hydrateIcons();
chat.setupConversationScroll();
document.querySelector('#session-title').textContent = '引导交互回归 · 独立测试';
document.querySelector('.topbar-actions').innerHTML = '<button id="check" class="primary-button">验收引导顺序</button><output id="result" style="max-width:160px;max-height:32px;overflow:hidden;font-size:10px">就绪</output>';
const original = { role: 'user', content: '请列出一个详细的工作计划。' };
const run = { sessionId: state.session.session_id, sequence: 0, started: Date.now(), message: { role: 'assistant', content: '先检查已有资料，再整理工作计划。', thinking: '检查任务背景。', segments: [], streaming: true, elapsed: 2 } };
chat.renderMessages([original]);
run.node = chat.appendMessage(run.message);
document.querySelector('#check').onclick = () => {
  const results = {};
  const oldNode = run.node, oldAnswer = oldNode.querySelector('.answer');
  const guidance = { role: 'user', content: '改为只给出三个重点。', guidance: true, guidance_id: 'steer-1' };
  const receipt = { id: 'steer-1', kind: 'steer', status: 'queued', payload: guidance.content };
  chat.projectEvent(run, { type: 'steering', sequence: 1, receipt, user_message: guidance });
  results.queued_guidance_follows_previous_answer = oldNode.nextElementSibling?._message?.guidance_id === guidance.guidance_id;
  results.queued_guidance_does_not_move_answer = document.querySelector('#messages').children[1] === oldNode;
  const previous = { ...run.message, streaming: false, steered: true };
  const next = { role: 'assistant', content: '', thinking: '', segments: [], pending: true };
  const boundary = { type: 'steering', sequence: 2, receipt: { ...receipt, status: 'delivered' }, previous_message: previous, message: next };
  chat.projectEvent(run, boundary);
  chat.projectEvent(run, boundary);
  results.replayed_receipt_does_not_duplicate_messages = document.querySelector('#messages').children.length === 4;
  results.old_answer_node_is_preserved = oldNode.querySelector('.answer') === oldAnswer && oldAnswer.textContent.includes('先检查');
  results.old_spinner_stops_at_guidance = !oldNode.querySelector('.spinner') && oldNode.textContent.includes('已按引导中断');
  results.next_answer_has_its_own_spinner = run.node !== oldNode && Boolean(run.node.querySelector('.spinner'));
  chat.projectEvent(run, { type: 'text', content: '1. 确定目标\n2. 完成工作\n3. 验证结果', sequence: 3 });
  chat.paintRun(run);
  results.old_and_new_answers_are_separate = !oldAnswer.textContent.includes('确定目标') && run.node.querySelector('.answer').textContent.includes('确定目标');
  const messages = [original, previous, guidance, { ...run.message, streaming: false, pending: false }];
  const order = () => [...document.querySelector('#messages').children].map(n => [n._message.role, n._message.content]);
  const liveOrder = JSON.stringify(order());
  chat.renderMessages(messages, { preserveView: true });
  results.final_save_preserves_order_and_old_node = JSON.stringify(order()) === liveOrder && document.querySelector('#messages').children[1] === oldNode;
  chat.renderMessages(messages);
  results.reload_has_same_order = JSON.stringify(order()) === liveOrder;
  const jumpButtons = [...document.querySelectorAll('#message-rail button')];
  results.history_jump_has_unique_targets = jumpButtons.length === 2 && new Set(jumpButtons.map(b => b.dataset.jump)).size === 2;
  results.guidance_badge_has_own_line = document.querySelector('.guidance-label')?.textContent === '引导';
  document.querySelector('#result').textContent = JSON.stringify({ passed: Object.values(results).every(Boolean), results });
  document.querySelector('#check').disabled = true;
  chat.bottom(true);
};
